 posted { job . get ( ' posted_at ' ) } 
 " f " { job . get ( ' apply_url ' ) or job . get ( ' posting_url ' ) } " ) def send ( text ): requests . post ( TELEGRAM , json = { " chat_id " : CHAT_ID , " text " : text , " parse_mode " : " HTML " , " disable_web_page_preview " : True }, timeout = 30 ) def main (): seen = set ( open ( " seen.txt " ). read (). split ()) if os . path . exists ( " seen.txt " ) else set () data = fetch () fresh = [ j for j in data [ " jobs " ] if j [ " _id " ] not in seen ] for job in fresh : send ( line ( job )) seen . add ( job [ " _id " ]) with open ( " seen.txt " , " w " ) as f : f . write ( " 
 " . join ( seen )) print ( f " { len ( fresh ) } new of { data [ ' total_count ' ] } matching " ) if __name__ == " __main__ " : main () Run it from cron every morning. seen.txt is the whole state: a posting is sent once and never again. Three things worth knowing before you build on it days_ago filters by the employer's publication date, not by when the index saw the row. That is why the median above is four days and not four hours — the filter is about the job, not about our crawler. Rows are not postings. A role advertised in three cities is three rows in search , one posting in the aggregate. If you count anything, count with /jobs/insights , which deduplicates; total_count on search is rows. Errors arrive as one envelope. Branch on error , never on the message text: { "error" : "invalid_request" , "message" : "days_ago: expected an integer" , "meta" : { "request_id" : "..." }} An unknown filter key is rejected with 422 and the message names the valid keys, so a typo never returns a silently wrong slice. An empty jobs array with total_count: 0 is a normal 200 — no matches is not an error. Making it yours Swap the filter and the bot changes job: {"keywords": ["kubernetes"], "days_ago": 3} — a stack watch {"handles": ["walmart:wd504:WalmartExternal"]} — one employer's careers page, by ATS board handle {"cities": ["Berlin"], "seniority": ["senior"], "salary": {"min": 80000}} — a narrow local search Send the same filter to /jobs/insights instead of /jobs/search and you get the market around your search — how many companies are hiring for it, where they are, and what they pay — in one request. The free plan is 200 postings and 5 insights calls a month, no card: get a key . Written with an AI assistant; every number and code snippet was run against the live HiringIndex API by the team before publishing.
